"use client";
// Order management: checkout tracking, merchant preparation, captain delivery and settlement.

import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Activity, ArrowDownToLine, BadgeCheck, Boxes, ClipboardList, CreditCard, LayoutDashboard, LogOut, Plus, RefreshCw, Search, ShieldCheck, Store, UserRound, Wallet } from "lucide-react";
import { createSupabaseBrowserClient } from "@/lib/supabase-browser";

type Profile = { id:string; display_name:string; phone:string|null; requested_role:string; approved_role:string; created_at:string };
type WalletRow = { id:string; owner_type:string; balance_iqd:number };
type StoreRow = { id:string; owner_id:string; name:string; category:string; is_approved:boolean; review_status:string; created_at:string; address:string; city:string; is_accepting_orders:boolean };
type ProductRow = { id:string; store_id:string; name:string; price_iqd:number; share_reward_iqd:number; merchant_commission_iqd:number; share_reward_enabled:boolean; is_available:boolean; description:string; image_url:string|null; availability_note:string; stock_quantity:number|null; preparation_time_minutes:number|null };
type TopupRow = { id:string; wallet_id:string; requested_by:string; amount_iqd:number; status:string; created_at:string; wallets?:{owner_id:string;owner_type:string}|null };
type OrderRow = { id:string; customer_id:string; store_id:string; captain_id:string|null; status:string; subtotal_iqd:number; delivery_fee_iqd:number; delivery_address?:string; created_at:string; stores?:{name:string;owner_id?:string}|{name:string;owner_id?:string}[]|null };
type Tab = "overview"|"profile"|"stores"|"products"|"wallet"|"orders"|"admin";
const roleLabel:Record<string,string>={customer:"کڕیار",merchant:"دوکاندار",captain:"کاپتن",admin:"ئەدمین",super_admin:"سوپەر ئەدمین"};
const categoryLabel:Record<string,string>={restaurant:"چێشتخانە",grocery:"سوپەرمارکێت",produce:"سەوزە و میوە"};
const statusLabel:Record<string,string>={pending:"چاوەڕوان",accepted:"وەرگیراوە",approved:"پەسەندکرا",rejected:"ڕەتکراوەتەوە",preparing:"ئامادەکردن",picked_up:"وەرگیرا لە دوکان",delivering:"لە ڕێگادایە",delivered:"گەیشتووە",completed:"تەواوبوو",cancelled:"هەڵوەشێنراوەتەوە"};
const money=(v:number)=>new Intl.NumberFormat("en-US").format(Number(v)||0)+" د.ع";
const panel="rounded-2xl border border-border bg-surface p-5 shadow-card";
const field="mt-2 w-full rounded-xl border border-border bg-surface px-4 py-3 text-sm outline-none focus:border-primary";

export default function DashboardPage(){
 const router=useRouter();
 const [profile,setProfile]=useState<Profile|null>(null);
 const [wallets,setWallets]=useState<WalletRow[]>([]);
 const [stores,setStores]=useState<StoreRow[]>([]);
 const [products,setProducts]=useState<ProductRow[]>([]);
 const [topups,setTopups]=useState<TopupRow[]>([]);
 const [orders,setOrders]=useState<OrderRow[]>([]);
 const [availableOrders,setAvailableOrders]=useState<OrderRow[]>([]);
 const [pendingRoles,setPendingRoles]=useState<Profile[]>([]);
 const [pendingStores,setPendingStores]=useState<StoreRow[]>([]);
 const [tab,setTab]=useState<Tab>("overview");
 const [orderSearch,setOrderSearch]=useState("");
 const [orderStatusFilter,setOrderStatusFilter]=useState("all");
 const [productSearch,setProductSearch]=useState("");
 const [adminOrderSearch,setAdminOrderSearch]=useState("");
 const [message,setMessage]=useState("");
 const [loading,setLoading]=useState(true);
 const [busy,setBusy]=useState(false);
 const [busyId,setBusyId]=useState("");
 const [editName,setEditName]=useState("");
 const [editPhone,setEditPhone]=useState("");
 const [storeName,setStoreName]=useState("");
 const [storeCategory,setStoreCategory]=useState("restaurant");
 const [storeAddress,setStoreAddress]=useState("");
 const [storeCity,setStoreCity]=useState("هەولێر");
 const [productStore,setProductStore]=useState("");
 const [editingProductId,setEditingProductId]=useState<string|null>(null);
 const [productStock,setProductStock]=useState("");
 const [productPrepMinutes,setProductPrepMinutes]=useState("");
 const [productName,setProductName]=useState("");
 const [productDescription,setProductDescription]=useState("");
 const [productImageUrl,setProductImageUrl]=useState("");
 const [productImageFile,setProductImageFile]=useState<File|null>(null);
 const [productAvailabilityNote,setProductAvailabilityNote]=useState("");
 const [productPrice,setProductPrice]=useState("");
 const [productCommission,setProductCommission]=useState("0");
 const [productReward,setProductReward]=useState("0");
 const [rewardEnabled,setRewardEnabled]=useState(false);
 const [topupWallet,setTopupWallet]=useState("");
 const [topupAmount,setTopupAmount]=useState("5000");

 const load=useCallback(async()=>{
  setLoading(true);
  const supabase=createSupabaseBrowserClient();
  const {data:{user},error:authError}=await supabase.auth.getUser();
  if(authError||!user){router.replace("/login");return;}
  try{
   const pendingRole=window.sessionStorage.getItem("shakh_google_signup_role");
   if(pendingRole){
    window.sessionStorage.removeItem("shakh_google_signup_role");
    const parsed:unknown=JSON.parse(pendingRole);
    if(parsed&&typeof parsed==="object"&&"role" in parsed&&"at" in parsed){
     const x=parsed as {role?:unknown;at?:unknown};
     if((x.role==="customer"||x.role==="merchant"||x.role==="captain")&&typeof x.at==="number"&&Date.now()-x.at<600000&&Date.now()>=x.at){
      const {error}=await supabase.from("profiles").update({requested_role:x.role}).eq("id",user.id).eq("approved_role","customer");
      if(error)setMessage("داواکاریی ڕۆڵ پاشەکەوت نەکرا. تکایە دووبارە هەوڵ بدە.");
     }
    }
   }
  }catch{window.sessionStorage.removeItem("shakh_google_signup_role");}
  const {data:me,error}=await supabase.from("profiles").select("id,display_name,phone,requested_role,approved_role,created_at").eq("id",user.id).single();
  if(error||!me){setMessage("نەتوانرا زانیاری هەژمار بخوێندرێتەوە.");setLoading(false);return;}
  const p=me as Profile;setProfile(p);setEditName(p.display_name||"");setEditPhone(p.phone||"");
  const admin=["admin","super_admin"].includes(p.approved_role);
  const [w,s,t,o,rr,ps,av]=await Promise.all([
   supabase.from("wallets").select("id,owner_type,balance_iqd").eq("owner_id",user.id),
   admin?supabase.from("stores").select("id,owner_id,name,category,is_approved,review_status,created_at,address,city,is_accepting_orders").order("created_at",{ascending:false}):supabase.from("stores").select("id,owner_id,name,category,is_approved,review_status,created_at,address,city,is_accepting_orders").eq("owner_id",user.id).order("created_at",{ascending:false}),
   admin?supabase.from("wallet_topup_requests").select("id,wallet_id,requested_by,amount_iqd,status,created_at,wallets(owner_id,owner_type)").order("created_at",{ascending:false}):supabase.from("wallet_topup_requests").select("id,wallet_id,requested_by,amount_iqd,status,created_at").eq("requested_by",user.id).order("created_at",{ascending:false}),
   admin?supabase.from("orders").select("id,customer_id,store_id,captain_id,status,subtotal_iqd,delivery_fee_iqd,delivery_address,created_at,stores(name)").order("created_at",{ascending:false}).limit(100):p.approved_role==="captain"?supabase.from("orders").select("id,customer_id,store_id,captain_id,status,subtotal_iqd,delivery_fee_iqd,delivery_address,created_at,stores(name)").eq("captain_id",user.id).order("created_at",{ascending:false}).limit(100):p.approved_role==="merchant"?supabase.from("orders").select("id,customer_id,store_id,captain_id,status,subtotal_iqd,delivery_fee_iqd,delivery_address,created_at,stores!inner(owner_id,name)").eq("stores.owner_id",user.id).order("created_at",{ascending:false}).limit(100):supabase.from("orders").select("id,customer_id,store_id,captain_id,status,subtotal_iqd,delivery_fee_iqd,delivery_address,created_at,stores(name)").eq("customer_id",user.id).order("created_at",{ascending:false}).limit(100),
   admin?supabase.from("profiles").select("id,display_name,phone,requested_role,approved_role,created_at").in("requested_role",["merchant","captain"]).neq("approved_role","merchant").neq("approved_role","captain").order("created_at",{ascending:true}):Promise.resolve({data:[],error:null}),
   admin?supabase.from("stores").select("id,owner_id,name,category,is_approved,review_status,created_at,address,city,is_accepting_orders").eq("review_status","pending").order("created_at",{ascending:true}):Promise.resolve({data:[],error:null}),
   p.approved_role==="captain"?supabase.from("orders").select("id,customer_id,store_id,captain_id,status,subtotal_iqd,delivery_fee_iqd,delivery_address,created_at,stores(name)").eq("status","pending").is("captain_id",null).order("created_at",{ascending:true}).limit(50):Promise.resolve({data:[],error:null})
  ]);
  const queryErrors=[w.error,s.error,t.error,o.error,rr.error,ps.error,av.error].filter(Boolean);
  if(queryErrors.length){
   console.error("Dashboard data query errors",queryErrors);
   setMessage(`هۆشداری: ${queryErrors.length} داواکاریی داتابەیس نەخوێندرایەوە. نوێکردنەوە بکە یان پۆلیسی دەستگەیشتن بپشکنە.`);
  }
  setWallets((w.data||[]) as WalletRow[]);setStores((s.data||[]) as StoreRow[]);setTopups((t.data||[]) as unknown as TopupRow[]);setOrders((o.data||[]) as OrderRow[]);setAvailableOrders((av.data||[]) as OrderRow[]);setPendingRoles((rr.data||[]) as Profile[]);setPendingStores((ps.data||[]) as StoreRow[]);
  const storeIds=((s.data||[]) as StoreRow[]).filter(x=>x.owner_id===user.id).map(x=>x.id);
  if(admin){
   const {data:all,error:productError}=await supabase.from("products").select("id,store_id,name,price_iqd,share_reward_iqd,merchant_commission_iqd,share_reward_enabled,is_available,description,image_url,availability_note,stock_quantity,preparation_time_minutes").order("name");
   if(productError){console.error("Dashboard products query error",productError);setMessage(current=>current||"نەتوانرا بەرهەمەکان بخوێندرێنەوە. پۆلیسی دەستگەیشتن بپشکنە.");}
   setProducts((all||[]) as ProductRow[]);
  } else if(storeIds.length){
   const {data:owned,error:productError}=await supabase.from("products").select("id,store_id,name,price_iqd,share_reward_iqd,merchant_commission_iqd,share_reward_enabled,is_available,description,image_url,availability_note,stock_quantity,preparation_time_minutes").in("store_id",storeIds).order("name");
   if(productError){console.error("Dashboard merchant products query error",productError);setMessage(current=>current||"نەتوانرا بەرهەمەکانی دوکان بخوێندرێنەوە.");}
   setProducts((owned||[]) as ProductRow[]);
  } else setProducts([]);
  setProductStore(current=>current||storeIds[0]||"");
  setTopupWallet(current=>current||((w.data||[]) as WalletRow[])[0]?.id||"");
  setLoading(false);
 },[router]);

 useEffect(()=>{void load();},[load]);
 const isAdmin=!!profile&&["admin","super_admin"].includes(profile.approved_role);
 const isMerchant=profile?.approved_role==="merchant";
 const isWorker=isMerchant||profile?.approved_role==="captain";
 const totalWallet=wallets.reduce((sum,w)=>sum+Number(w.balance_iqd),0);
 const pendingTopups=topups.filter(t=>t.status==="pending");
 const activeOrders=orders.filter(o=>["accepted","preparing","picked_up","delivering"].includes(o.status)).length;
 const deliveredOrders=orders.filter(o=>["delivered","completed"].includes(o.status)).length;
 const availableProducts=products.filter(p=>p.is_available).length;
 const filteredOrders=useMemo(()=>orders.filter(o=>(orderStatusFilter==="all"||o.status===orderStatusFilter)&&[o.id,o.delivery_address||"",Array.isArray(o.stores)?o.stores[0]?.name||"":o.stores?.name||""].join(" ").toLocaleLowerCase().includes(orderSearch.trim().toLocaleLowerCase())),[orders,orderSearch,orderStatusFilter]);
 const filteredProducts=useMemo(()=>products.filter(p=>[p.name,p.description,p.availability_note].join(" ").toLocaleLowerCase().includes(productSearch.trim().toLocaleLowerCase())),[products,productSearch]);
 const filteredAdminOrders=useMemo(()=>orders.filter(o=>[o.id,o.status,o.delivery_address||"",Array.isArray(o.stores)?o.stores[0]?.name||"":o.stores?.name||""].join(" ").toLocaleLowerCase().includes(adminOrderSearch.trim().toLocaleLowerCase())),[orders,adminOrderSearch]);
 const tabs=useMemo(()=>[
  {id:"overview" as Tab,label:"پوختە",icon:LayoutDashboard},
  {id:"profile" as Tab,label:"هەژمار",icon:UserRound},
  ...(isMerchant?[{id:"stores" as Tab,label:"دوکان",icon:Store},{id:"products" as Tab,label:"بەرهەم",icon:Boxes}]:[]),
  ...(isWorker?[{id:"wallet" as Tab,label:"جزدان",icon:Wallet}]:[]),
  {id:"orders" as Tab,label:"داواکاری",icon:ClipboardList},
  ...(isAdmin?[{id:"admin" as Tab,label:"بەڕێوەبردن",icon:ShieldCheck}]:[])
 ],[isAdmin,isMerchant,isWorker]);

 async function saveProfile(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMessage("");try{const sb=createSupabaseBrowserClient();const {data:{user}}=await sb.auth.getUser();if(!user)throw new Error("دووبارە بچۆ ژوورەوە.");const name=editName.trim();if(name.length<2)throw new Error("ناو لانیکەم ٢ پیت بێت.");const {error}=await sb.from("profiles").update({display_name:name,phone:editPhone.trim()||null}).eq("id",user.id);if(error)throw error;setMessage("زانیاری هەژمار نوێ کرایەوە.");await load();}catch(e){setMessage(e instanceof Error?e.message:"هەڵەی نوێکردنەوە.");}finally{setBusy(false);}}
 async function createStore(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMessage("");try{const sb=createSupabaseBrowserClient();const {data:{user}}=await sb.auth.getUser();if(!user)throw new Error("چوونەژوورەوە پێویستە.");const name=storeName.trim();if(name.length<2)throw new Error("ناوی دوکان زۆر کورتە.");const {error}=await sb.from("stores").insert({owner_id:user.id,name,category:storeCategory,address:storeAddress.trim(),city:storeCity.trim(),is_approved:false});if(error)throw error;setStoreName("");setStoreAddress("");setMessage("دوکان تۆمار کرا و چاوەڕێی پەسەندکردنی سوپەر ئەدمینە.");await load();}catch(e){setMessage(e instanceof Error?e.message:"دروستکردنی دوکان سەرکەوتوو نەبوو.");}finally{setBusy(false);}}
 async function createProduct(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMessage("");try{const price=Number(productPrice),commission=Number(productCommission),reward=Number(productReward),stock=productStock.trim()===""?null:Number(productStock),prep=productPrepMinutes.trim()===""?null:Number(productPrepMinutes);if(!productStore)throw new Error("سەرەتا دوکانێک دروست بکە.");if(productName.trim().length<2)throw new Error("ناوی بەرهەم لانیکەم ٢ پیت بێت.");if(!Number.isSafeInteger(price)||price<1||!Number.isSafeInteger(commission)||commission<0||!Number.isSafeInteger(reward)||reward<0)throw new Error("نرخ و کۆمسیۆن دەبێت ژمارەی دروست و نەنەرێنی بن.");if(stock!==null&&(!Number.isSafeInteger(stock)||stock<0))throw new Error("ژمارەی ستۆک دەبێت سفر یان ژمارەیەکی گەورەتر بێت.");if(prep!==null&&(!Number.isSafeInteger(prep)||prep<1||prep>1440))throw new Error("کاتی ئامادەکردن لە ١ تا ١٤٤٠ خولەک بێت.");if(productImageUrl.trim()&&!/^https:\/\//i.test(productImageUrl.trim()))throw new Error("لینکی وێنە دەبێت بە https:// دەست پێ بکات.");if(productImageFile&&(!["image/jpeg","image/png","image/webp"].includes(productImageFile.type)||productImageFile.size>5*1024*1024))throw new Error("وێنە دەبێت JPG/PNG/WEBP و بچووکتر لە ٥MB بێت.");const sb=createSupabaseBrowserClient();let imageUrl=productImageUrl.trim()||null;if(productImageFile){const ext=productImageFile.type==="image/png"?"png":productImageFile.type==="image/webp"?"webp":"jpg";const path=productStore+"/"+crypto.randomUUID()+"."+ext;const {error:uploadError}=await sb.storage.from("product-images").upload(path,productImageFile,{contentType:productImageFile.type,upsert:false});if(uploadError)throw uploadError;imageUrl=sb.storage.from("product-images").getPublicUrl(path).data.publicUrl;}const values={store_id:productStore,name:productName.trim(),description:productDescription.trim(),image_url:imageUrl,availability_note:productAvailabilityNote.trim(),price_iqd:price,merchant_commission_iqd:commission,share_reward_iqd:reward,share_reward_enabled:rewardEnabled,stock_quantity:stock,preparation_time_minutes:prep};const result=editingProductId?await sb.from("products").update(values).eq("id",editingProductId).eq("store_id",productStore):await sb.from("products").insert({...values,is_available:true});if(result.error)throw result.error;setProductName("");setProductDescription("");setProductImageUrl("");setProductImageFile(null);setProductAvailabilityNote("");setProductPrice("");setProductCommission("0");setProductReward("0");setRewardEnabled(false);setProductStock("");setProductPrepMinutes("");setEditingProductId(null);setMessage(editingProductId?"زانیاریی بەرهەم نوێ کرایەوە.":"بەرهەم زیاد کرا.");await load();}catch(e){setMessage(e instanceof Error?e.message:"پاشەکەوتکردنی بەرهەم سەرکەوتوو نەبوو.");}finally{setBusy(false);}}
 async function requestTopup(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMessage("");try{const amount=Number(topupAmount);if(!topupWallet||!Number.isSafeInteger(amount)||amount<1000)throw new Error("جزدان هەڵبژێرە و بڕی کەمتر لە ١٠٠٠ مەنووسە.");const sb=createSupabaseBrowserClient();const {data:{user}}=await sb.auth.getUser();if(!user)throw new Error("چوونەژوورەوە پێویستە.");const {error}=await sb.from("wallet_topup_requests").insert({wallet_id:topupWallet,requested_by:user.id,amount_iqd:amount,status:"pending"});if(error)throw error;setMessage("داواکاریی زیادکردنی باڵانس نێردرا بۆ سوپەر ئەدمین.");await load();}catch(e){setMessage(e instanceof Error?e.message:"ناردنی داواکاری سەرکەوتوو نەبوو.");}finally{setBusy(false);}}
 function startEditProduct(p:ProductRow){setEditingProductId(p.id);setProductStore(p.store_id);setProductName(p.name);setProductDescription(p.description||"");setProductImageUrl(p.image_url||"");setProductImageFile(null);setProductAvailabilityNote(p.availability_note||"");setProductPrice(String(p.price_iqd));setProductCommission(String(p.merchant_commission_iqd));setProductReward(String(p.share_reward_iqd));setRewardEnabled(p.share_reward_enabled);setProductStock(p.stock_quantity===null?"":String(p.stock_quantity));setProductPrepMinutes(p.preparation_time_minutes===null?"":String(p.preparation_time_minutes));window.scrollTo({top:0,behavior:"smooth"});}
 function cancelEditProduct(){setEditingProductId(null);setProductName("");setProductDescription("");setProductImageUrl("");setProductImageFile(null);setProductAvailabilityNote("");setProductPrice("");setProductCommission("0");setProductReward("0");setRewardEnabled(false);setProductStock("");setProductPrepMinutes("");}
 async function toggleProductAvailability(product:ProductRow){
  setBusyId(product.id);setMessage("");
  try{const sb=createSupabaseBrowserClient();const {error}=await sb.from("products").update({is_available:!product.is_available}).eq("id",product.id);if(error)throw error;setMessage(product.is_available?"بەرهەم لە بازاڕ شاردراوە.":"بەرهەم دووبارە بەردەست کرا.");await load();}
  catch(e){setMessage(e instanceof Error?e.message:"گۆڕینی بەردەستبوونی بەرهەم سەرکەوتوو نەبوو.");}
  finally{setBusyId("");}
 }
 async function toggleStoreOrders(store:StoreRow){
  setBusyId(store.id);setMessage("");
  try{const sb=createSupabaseBrowserClient();const {error}=await sb.from("stores").update({is_accepting_orders:!store.is_accepting_orders}).eq("id",store.id);if(error)throw error;setMessage(store.is_accepting_orders?"وەرگرتنی داواکاری بۆ دوکان وەستاندرا.":"دوکان دووبارە داواکاری وەردەگرێت.");await load();}
  catch(e){setMessage(e instanceof Error?e.message:"گۆڕینی دۆخی داواکاری دوکان سەرکەوتوو نەبوو.");}
  finally{setBusyId("");}
 }
 async function claimOrder(id:string){setBusyId(id);setMessage("");try{const sb=createSupabaseBrowserClient();const {error}=await sb.rpc("claim_delivery_order",{target_order_id:id});if(error)throw error;setMessage("داواکارییەکە بۆ تۆ تەرخان کرا.");await load();}catch(e){setMessage(e instanceof Error?e.message:"وەرگرتنی داواکاری سەرکەوتوو نەبوو.");}finally{setBusyId("");}}
 async function advanceOrder(id:string,status:string){setBusyId(id);setMessage("");try{const sb=createSupabaseBrowserClient();const {error}=await sb.rpc("advance_shakh_order",{target_order_id:id,next_status:status});if(error)throw error;setMessage(status==="delivered"?"گەیاندن تەواو بوو و حیساباتی دارایی جێبەجێ کرا.":"دۆخی داواکاری نوێ کرایەوە.");await load();}catch(e){setMessage(e instanceof Error?e.message:"گۆڕینی دۆخی داواکاری سەرکەوتوو نەبوو.");}finally{setBusyId("");}}
 async function reviewRole(id:string,approve:boolean){setBusyId(id);setMessage("");try{const sb=createSupabaseBrowserClient();const {error}=await sb.rpc("review_role_request",{target_user_id:id,approve});if(error)throw error;setMessage(approve?"ڕۆڵ پەسەند کرا و جزدان دروست کرا.":"داواکاریی ڕۆڵ ڕەتکرایەوە.");await load();}catch(e){setMessage(e instanceof Error?e.message:"کردارەکە سەرکەوتوو نەبوو.");}finally{setBusyId("");}}
 async function reviewTopup(id:string,approve:boolean){setBusyId(id);setMessage("");try{const sb=createSupabaseBrowserClient();const {error}=await sb.rpc("review_wallet_topup",{target_request_id:id,approve});if(error)throw error;setMessage(approve?"داواکاری پەسەند کرا و باڵانس بە شێوەی پارێزراو زیاد کرا.":"داواکاری ڕەتکرایەوە.");await load();}catch(e){setMessage(e instanceof Error?e.message:"پشکنینی داواکاری سەرکەوتوو نەبوو.");}finally{setBusyId("");}}
 async function reviewStore(id:string,approve:boolean){setBusyId(id);setMessage("");try{const sb=createSupabaseBrowserClient();const {error}=await sb.rpc("review_store",{target_store_id:id,approve});if(error)throw error;setMessage(approve?"دوکان پەسەند کرا.":"پەسەندنەکردنی دوکان تۆمار کرا.");await load();}catch(e){setMessage(e instanceof Error?e.message:"پشکنینی دوکان سەرکەوتوو نەبوو.");}finally{setBusyId("");}}
 async function signOut(){const sb=createSupabaseBrowserClient();await sb.auth.signOut();router.replace("/login");router.refresh();}

 if(loading)return <main dir="rtl" className="min-h-screen bg-background p-8 text-text-primary">داشبۆرد بار دەکرێت...</main>;
 const selectedTab=(id:Tab)=>setTab(id);
 return <main dir="rtl" className="min-h-screen bg-background pb-28 text-text-primary md:pb-10">
  <div className="mx-auto max-w-7xl px-3 py-4 sm:px-6 sm:py-8">
   <header className="flex flex-wrap items-center justify-between gap-4 rounded-3xl bg-primary p-5 text-white sm:p-8">
    <div className="flex items-center gap-3"><span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/15"><LayoutDashboard size={24}/></span><div><h1 className="text-2xl font-black sm:text-3xl">داشبۆرد</h1><p className="mt-1 text-sm text-white/80">{profile?.display_name||"بەکارهێنەر"} · {roleLabel[profile?.approved_role||""]}</p><p className="mt-2 text-xs text-white/70">بەڕێوەبردنی تایبەت بە ڕۆڵ · کوردیی سۆرانی · دیناری عێراقی</p></div></div>
    <div className="flex flex-wrap gap-2"><Link href="/" className="rounded-xl bg-white px-4 py-2 text-sm font-bold text-primary">بازاڕ</Link><button onClick={()=>void load()} disabled={loading} aria-label="نوێکردنەوەی زانیارییەکان" title="نوێکردنەوەی زانیارییەکان" className="flex items-center gap-2 rounded-xl border border-white/30 px-3 py-2 text-sm font-bold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white disabled:opacity-50"><RefreshCw size={18} className={loading?"animate-spin":""}/><span className="hidden sm:inline">{loading?"نوێ دەکرێتەوە":"نوێکردنەوە"}</span></button><button onClick={()=>void signOut()} className="flex items-center gap-2 rounded-xl border border-white/30 px-3 py-2 text-sm font-bold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white"><LogOut size={16}/> دەرچوون</button></div>
   </header>
   {message&&<div role="status" aria-live="polite" className="mt-4 rounded-xl border border-border bg-surface p-4 text-sm leading-7">{message}</div>}
   <div className="mt-5 grid gap-5 lg:grid-cols-[230px_minmax(0,1fr)]">
    <aside className="hidden self-start rounded-2xl border border-border bg-surface p-3 lg:block"><p className="px-3 py-2 text-xs font-bold text-text-muted">بەشی هەژمار</p>{tabs.map(item=><button key={item.id} onClick={()=>selectedTab(item.id)} aria-current={tab===item.id?"page":undefined} className={"mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right text-sm font-bold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary "+(tab===item.id?"bg-secondary text-primary":"text-text-secondary hover:bg-surface-muted")}><item.icon size={18}/>{item.label}</button>)}<div className="mt-4 border-t border-border px-3 pt-4 text-xs leading-6 text-text-muted">شاخ دێلڤەری<br/>بەڕێوەبردنی هەژمار و خزمەتگوزارییەکان</div></aside>
    <section className="min-w-0">
     <div className="mb-4 flex gap-2 overflow-x-auto pb-1 lg:hidden">{tabs.map(item=><button key={item.id} onClick={()=>selectedTab(item.id)} aria-current={tab===item.id?"page":undefined} className={"flex shrink-0 items-center gap-2 rounded-xl border px-3 py-2 text-sm font-bold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary "+(tab===item.id?"border-primary bg-primary text-white":"border-border bg-surface text-text-secondary")}><item.icon size={16}/>{item.label}</button>)}</div>
     {tab==="overview"&&<div className="space-y-5"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
       <article className={panel}><p className="text-sm text-text-secondary">ڕۆڵی هەژمار</p><h2 className="mt-2 text-xl font-black">{roleLabel[profile?.approved_role||""]}</h2><p className="mt-2 text-xs text-text-muted">داواکراو: {roleLabel[profile?.requested_role||""]}</p></article>
       {wallets.length>0&&<article className={panel}><p className="text-sm text-text-secondary">کۆی باڵانسی جزدان</p><h2 className="mt-2 text-xl font-black">{money(totalWallet)}</h2><p className="mt-2 text-xs text-text-muted">{wallets.length} جزدان</p></article>}
       {(isMerchant||isAdmin)&&<article className={panel}><p className="text-sm text-text-secondary">{isAdmin?"هەموو دوکانەکان":"دوکانەکانم"}</p><h2 className="mt-2 text-xl font-black">{isAdmin?stores.length:stores.filter(s=>s.owner_id===profile?.id).length}</h2><p className="mt-2 text-xs text-text-muted">پەسەندکراو: {isAdmin?stores.filter(s=>s.is_approved).length:stores.filter(s=>s.owner_id===profile?.id&&s.is_approved).length}</p></article>}
       <article className={panel}><p className="text-sm text-text-secondary">{isAdmin?"کۆی داواکارییەکان":profile?.approved_role==="captain"?"گەیاندنەکانم":isMerchant?"داواکارییەکانی دوکان":"داواکارییەکانی من"}</p><h2 className="mt-2 text-xl font-black">{orders.length}</h2><p className="mt-2 text-xs text-text-muted">{isAdmin?"لە سنووری داتاکانی بەڕێوەبەر":profile?.approved_role==="captain"?"تەرخانکراو بۆ کاپتن":"پەیوەست بە هەژمارەکەت"}</p></article>
       <article className={panel}><p className="text-sm text-text-secondary">داواکاریی چالاک</p><h2 className="mt-2 text-xl font-black">{activeOrders}</h2><p className="mt-2 text-xs text-text-muted">لە وەرگرتن تا گەیاندن</p></article>{profile?.approved_role==="captain"&&<article className={panel}><p className="text-sm text-text-secondary">داواکاریی بەردەست</p><h2 className="mt-2 text-xl font-black">{availableOrders.length}</h2><p className="mt-2 text-xs text-text-muted">چاوەڕوانی وەرگرتنی کاپتن</p></article>}{isAdmin&&<article className={panel}><p className="text-sm text-text-secondary">چاوەڕوانی بەڕێوەبردن</p><h2 className="mt-2 text-xl font-black">{pendingRoles.length+pendingStores.length+pendingTopups.length}</h2><p className="mt-2 text-xs text-text-muted">ڕۆڵ، دوکان و جزدان</p></article>}
       <article className={panel}><p className="text-sm text-text-secondary">گەیاندنی تەواوکراو</p><h2 className="mt-2 text-xl font-black">{deliveredOrders}</h2><p className="mt-2 text-xs text-text-muted">داواکاریی گەیشتوو یان تەواوبوو</p></article>
       {(isMerchant||isAdmin)&&<article className={panel}><p className="text-sm text-text-secondary">بەرهەمەکان</p><h2 className="mt-2 text-xl font-black">{products.length}</h2><p className="mt-2 text-xs text-text-muted">بەردەست: {availableProducts}</p></article>}
      </div>
      {profile?.requested_role!=="customer"&&profile?.approved_role==="customer"&&<div className="rounded-2xl border border-warning/30 bg-surface p-5"><h2 className="font-black">چاوەڕێی پەسەندکردنی ڕۆڵ</h2><p className="mt-2 text-sm leading-7 text-text-secondary">داواکاریی {roleLabel[profile.requested_role]} هێشتا پەسەند نەکراوە. هەتا ئەو کاتە دەسەڵاتی ئەو ڕۆڵەت نییە.</p></div>}
      <div className={panel}><h2 className="text-lg font-black">خێرا بڕۆ بۆ</h2><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{tabs.filter(x=>x.id!=="overview").map(x=><button key={x.id} onClick={()=>setTab(x.id)} className="flex items-center gap-3 rounded-xl border border-border p-4 text-right hover:border-primary hover:bg-secondary"><x.icon className="text-primary" size={20}/><span className="font-bold">{x.label}</span></button>)}</div></div>
     </div>}
     {tab==="profile"&&<div className={panel}><h2 className="text-xl font-black">زانیاری هەژمار</h2><p className="mt-1 text-sm leading-6 text-text-secondary">زانیاری بنەڕەتی نوێ بکەرەوە. ڕۆڵ و دەسەڵات لێرە ناگۆڕدرێت.</p><form onSubmit={saveProfile} className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-sm font-bold">ناوی تەواو<input required minLength={2} maxLength={100} value={editName} onChange={e=>setEditName(e.target.value)} className={field}/></label><label className="text-sm font-bold">ژمارەی مۆبایل<input type="tel" maxLength={30} value={editPhone} onChange={e=>setEditPhone(e.target.value)} className={field}/></label><div className="flex flex-wrap gap-2 sm:col-span-2"><button disabled={busy} className="rounded-xl bg-primary px-5 py-3 font-bold text-white disabled:opacity-50">{busy?"چاوەڕێ بکە...":"پاشەکەوتکردن"}</button><Link href="/reset-password" className="rounded-xl border border-border px-5 py-3 text-sm font-bold">گۆڕینی وشەی نهێنی</Link></div></form><div className="mt-6 rounded-xl bg-surface-muted p-4 text-sm leading-7"><p><b>ئیمەیڵ:</b> زانیاریی چوونەژوورەوە لە Supabase Auth بەڕێوەدەبرێت.</p><p><b>ڕۆڵی چالاک:</b> {roleLabel[profile?.approved_role||""]}</p><p><b>ڕۆڵی داواکراو:</b> {roleLabel[profile?.requested_role||""]}</p></div></div>}
     {tab==="stores"&&isMerchant&&<div className="space-y-5"><div className={panel}><h2 className="text-xl font-black">دروستکردنی دوکان</h2><p className="mt-1 text-sm leading-6 text-text-secondary">دوکان سەرەتا دەبێت لەلایەن سوپەر ئەدمین پەسەند بکرێت.</p><form onSubmit={createStore} className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-sm font-bold">ناوی دوکان<input required minLength={2} maxLength={100} value={storeName} onChange={e=>setStoreName(e.target.value)} placeholder="بۆ نموونە: چێشتخانەی شاخ" className={field}/></label><label className="text-sm font-bold">شار<input maxLength={120} value={storeCity} onChange={e=>setStoreCity(e.target.value)} placeholder="هەولێر" className={field}/></label><label className="text-sm font-bold sm:col-span-2">ناونیشانی دوکان<textarea maxLength={500} value={storeAddress} onChange={e=>setStoreAddress(e.target.value)} placeholder="گەڕەک، شەقام و نیشانەی نزیک" className={field}/></label><label className="text-sm font-bold">جۆری دوکان<select value={storeCategory} onChange={e=>setStoreCategory(e.target.value)} className={field}><option value="restaurant">چێشتخانە</option><option value="grocery">سوپەرمارکێت</option><option value="produce">سەوزە و میوە</option></select></label><div className="sm:col-span-2"><button disabled={busy} className="flex items-center gap-2 rounded-xl bg-primary px-5 py-3 font-bold text-white disabled:opacity-50"><Plus size={18}/> تۆمارکردنی دوکان</button></div></form></div><div className={panel}><h2 className="text-lg font-black">دوکانەکانم</h2><div className="mt-4 space-y-3">{stores.filter(s=>s.owner_id===profile?.id).length===0?<p className="text-sm text-text-secondary">هێشتا دوکانێکت تۆمار نەکردووە.</p>:stores.filter(s=>s.owner_id===profile?.id).map(s=><div key={s.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border p-4"><div><b>{s.name}</b><p className="mt-1 text-sm text-text-secondary">{categoryLabel[s.category]||s.category} · {s.city||"شار دیاری نەکراوە"}</p>{s.address&&<p className="mt-1 text-xs text-text-muted">{s.address}</p>}</div><span className={"rounded-full px-3 py-1 text-xs font-bold "+(s.review_status==="approved"?"bg-secondary text-primary":s.review_status==="rejected"?"bg-orange-100 text-orange-800":"bg-surface-muted text-text-secondary")}>{s.review_status==="approved"?"پەسەندکرا":s.review_status==="rejected"?"ڕەتکراوەتەوە":"چاوەڕێی پەسەندکردن"}</span>{s.is_approved&&<button disabled={busyId===s.id} onClick={()=>void toggleStoreOrders(s)} className="rounded-xl border border-border px-3 py-2 text-xs font-bold disabled:opacity-50">{s.is_accepting_orders?"وەستاندنی وەرگرتنی داوا":"وەرگرتنی داوا چالاک بکە"}</button>}</div>)}</div></div></div>}
     {tab==="products"&&isMerchant&&<div className="space-y-5"><div className={panel}><h2 className="text-xl font-black">{editingProductId?"دەستکاریکردنی بەرهەم":"زیادکردنی بەرهەم"}</h2><form onSubmit={createProduct} className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-sm font-bold sm:col-span-2">دوکان<select required disabled={!!editingProductId} value={productStore} onChange={e=>setProductStore(e.target.value)} className={field}><option value="">دوکان هەڵبژێرە</option>{stores.filter(s=>s.owner_id===profile?.id&&s.is_approved).map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><p className="sm:col-span-2 -mt-2 text-xs text-text-muted">تەنها دوکانی پەسەندکراو دەتوانێت بەرهەمی بازاڕ زیاد بکات.</p><label className="text-sm font-bold">ناوی بەرهەم<input required minLength={2} maxLength={120} value={productName} onChange={e=>setProductName(e.target.value)} className={field}/></label><label className="text-sm font-bold sm:col-span-2">وەسفی بەرهەم<textarea maxLength={2000} value={productDescription} onChange={e=>setProductDescription(e.target.value)} placeholder="ناوەڕۆک، پێکهاتە یان تایبەتمەندییەکان" className={field}/></label><label className="text-sm font-bold sm:col-span-2">بارکردنی وێنە (JPG/PNG/WEBP، تا ٥MB)<input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>setProductImageFile(e.target.files?.[0]||null)} className={field}/></label>{productImageFile&&<p className="sm:col-span-2 text-xs text-text-secondary">وێنەی هەڵبژێردراو: {productImageFile.name}</p>}<label className="text-sm font-bold sm:col-span-2">یان لینکی وێنە (HTTPS)<input type="url" maxLength={2048} value={productImageUrl} onChange={e=>setProductImageUrl(e.target.value)} placeholder="https://..." className={field}/></label><label className="text-sm font-bold sm:col-span-2">بەردەستبوون و کاتی داواکردن<input maxLength={300} value={productAvailabilityNote} onChange={e=>setProductAvailabilityNote(e.target.value)} placeholder="بۆ نموونە: هەموو ڕۆژێک، ئامادەکردن ٢٠ خولەک" className={field}/></label><label className="text-sm font-bold">نرخ بە دینار<input required type="number" min="1" step="1" value={productPrice} onChange={e=>setProductPrice(e.target.value)} className={field}/></label><label className="text-sm font-bold">ژمارەی ستۆک (بەتاڵ = بێ سنوور)<input type="number" min="0" step="1" value={productStock} onChange={e=>setProductStock(e.target.value)} className={field} placeholder="بۆ نموونە: ٢٠"/></label><label className="text-sm font-bold">کاتی ئامادەکردن بە خولەک<input type="number" min="1" max="1440" step="1" value={productPrepMinutes} onChange={e=>setProductPrepMinutes(e.target.value)} className={field} placeholder="بۆ نموونە: ٢٥"/></label><label className="text-sm font-bold">کۆمسیۆنی دوکان (د.ع)<input required type="number" min="0" step="1" value={productCommission} onChange={e=>setProductCommission(e.target.value)} className={field}/></label><label className="text-sm font-bold">پاداشتی هاوبەشکردن (د.ع)<input required type="number" min="0" step="1" value={productReward} onChange={e=>setProductReward(e.target.value)} className={field}/></label><label className="flex items-center gap-3 text-sm font-bold sm:col-span-2"><input type="checkbox" checked={rewardEnabled} onChange={e=>setRewardEnabled(e.target.checked)} className="h-4 w-4 accent-orange-600"/> پاداشتی هاوبەشکردن چالاک بێت</label><div className="sm:col-span-2"><button disabled={busy||!stores.some(s=>s.owner_id===profile?.id&&s.id===productStore&&s.is_approved)} className="rounded-xl bg-primary px-5 py-3 font-bold text-white disabled:opacity-50">{editingProductId?"پاشەکەوتکردنی گۆڕانکاری":"زیادکردنی بەرهەم"}</button>{editingProductId&&<button type="button" onClick={cancelEditProduct} className="mr-2 rounded-xl border border-border px-4 py-3 font-bold">پاشگەزبوونەوە</button>}</div></form></div><div className={panel}><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-black">بەرهەمەکانم ({products.length})</h2><p className="mt-1 text-xs text-text-muted">بەردەست: {availableProducts} · شاراوە: {products.length-availableProducts}</p></div><label className="relative min-w-[220px] flex-1 sm:max-w-sm"><span className="sr-only">گەڕان لە بەرهەمەکان</span><Search size={17} className="absolute right-3 top-1/2 -translate-y-1/2 text-text-muted"/><input value={productSearch} onChange={e=>setProductSearch(e.target.value)} placeholder="گەڕان بە ناو یان وەسف..." className="w-full rounded-xl border border-border bg-surface px-10 py-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/20"/></label></div><div className="mt-4 space-y-3">{products.length===0?<p className="text-sm text-text-secondary">هێشتا بەرهەمێک زیاد نەکراوە.</p>:filteredProducts.length===0?<p className="rounded-xl bg-surface-muted p-4 text-sm text-text-secondary">هیچ بەرهەمێک لەگەڵ گەڕانەکە ناگونجێت.</p>:filteredProducts.map(p=><article key={p.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border p-4">{p.image_url&&<img src={p.image_url} alt={p.name} loading="lazy" className="h-20 w-20 rounded-xl border border-border object-cover"/>}<div className="min-w-0 flex-1"><b>{p.name}</b><p className="mt-1 text-sm text-text-secondary">{p.description||"وەسفی بەرهەم تۆمار نەکراوە."}</p><p className="mt-1 text-sm text-text-secondary">{money(p.price_iqd)} · کۆمسیۆن: {money(p.merchant_commission_iqd)}{p.share_reward_enabled?" · پاداشتی هاوبەشکردن: "+money(p.share_reward_iqd):""}</p>{p.availability_note&&<p className="mt-1 text-xs text-text-muted">بەردەستبوون: {p.availability_note}</p>}{p.stock_quantity!==null&&<p className="mt-1 text-xs text-text-muted">ماوە: {p.stock_quantity} دانە</p>}{p.preparation_time_minutes!==null&&<p className="mt-1 text-xs text-text-muted">کاتی ئامادەکردن: {p.preparation_time_minutes} خولەک</p>}</div><div className="flex flex-col items-end gap-2"><span className={"rounded-full px-3 py-1 text-xs font-bold "+(p.is_available?"bg-secondary text-primary":"bg-surface-muted text-text-muted")}>{p.is_available?"بەردەستە":"نا بەردەستە"}</span><button disabled={busyId===p.id} onClick={()=>startEditProduct(p)} className="rounded-lg border border-border px-3 py-2 text-xs font-bold">دەستکاری</button><button disabled={busyId===p.id} onClick={()=>void toggleProductAvailability(p)} className="rounded-lg border border-border px-3 py-2 text-xs font-bold disabled:opacity-50">{p.is_available?"لە بازاڕ بشارەوە":"بەردەست بکە"}</button></div></article>)}</div></div></div>}
     {tab==="wallet"&&isWorker&&<div className="space-y-5"><div className="grid gap-3 sm:grid-cols-2">{wallets.map(w=><article key={w.id} className={panel}><div className="flex items-center gap-2 text-sm text-text-secondary"><Wallet size={18}/> جزدانی {roleLabel[w.owner_type]||w.owner_type}</div><h2 className="mt-3 text-3xl font-black">{money(w.balance_iqd)}</h2><p className="mt-2 text-xs text-text-muted">باڵانس بە داتابەیسەوە پەیوەستە.</p></article>)}</div><div className={panel}><h2 className="text-xl font-black">داواکاریی زیادکردنی باڵانس</h2><p className="mt-1 text-sm leading-6 text-text-secondary">داواکاری بۆ سوپەر ئەدمین دەنێردرێت. باڵانس تەنها دوای پەسەندکردن زیاد دەکرێت.</p><form onSubmit={requestTopup} className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-sm font-bold">جزدان<select required value={topupWallet} onChange={e=>setTopupWallet(e.target.value)} className={field}>{wallets.filter(w=>["merchant","captain"].includes(w.owner_type)).map(w=><option key={w.id} value={w.id}>{roleLabel[w.owner_type]} · {money(w.balance_iqd)}</option>)}</select></label><label className="text-sm font-bold">بڕ بە دینار<input required type="number" min="1000" step="1" value={topupAmount} onChange={e=>setTopupAmount(e.target.value)} className={field}/></label><div className="sm:col-span-2"><button disabled={busy||!wallets.some(w=>["merchant","captain"].includes(w.owner_type))} className="rounded-xl bg-primary px-5 py-3 font-bold text-white disabled:opacity-50">ناردنی داواکاری</button></div></form></div><div className={panel}><h2 className="text-lg font-black">مێژووی داواکارییەکان</h2><div className="mt-4 space-y-3">{topups.length===0?<p className="text-sm text-text-secondary">هێشتا داواکارییەک نییە.</p>:topups.map(t=><div key={t.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border p-4"><div><b>{money(t.amount_iqd)}</b><p className="mt-1 text-xs text-text-muted">{new Date(t.created_at).toLocaleString("ckb")}</p></div><span className="rounded-full bg-surface-muted px-3 py-1 text-xs font-bold">{statusLabel[t.status]||t.status}</span></div>)}</div></div></div>}
     {tab==="orders"&&<div className="space-y-5">
      {profile?.approved_role==="captain"&&<div className={panel}><h2 className="text-xl font-black">داواکارییە بەردەستەکان</h2><p className="mt-1 text-sm text-text-secondary">داواکارییەک وەربگرە؛ تەرخانکردن لە سێرڤەرەوە پارێزراوە.</p><div className="mt-4 space-y-3">{availableOrders.length===0?<p className="rounded-xl bg-surface-muted p-4 text-sm text-text-secondary">ئێستا داواکاریی بەردەست نییە.</p>:availableOrders.map(o=><article key={o.id} className="rounded-xl border border-border p-4"><div className="flex flex-wrap justify-between gap-2"><b>داواکاری #{o.id.slice(0,8)}</b><b>{money(o.subtotal_iqd+o.delivery_fee_iqd)}</b></div><p className="mt-2 text-sm leading-7 text-text-secondary">ناونیشان: {o.delivery_address||"ناونیشان تۆمار نەکراوە"}</p><p className="text-xs text-text-muted">{new Date(o.created_at).toLocaleString("ckb")}</p><button disabled={!!busyId} onClick={()=>void claimOrder(o.id)} className="mt-3 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">وەرگرتنی داواکاری</button></article>)}</div></div>}
      <div className={panel}><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-xl font-black">{profile?.approved_role==="captain"?"گەیاندنەکانی من":profile?.approved_role==="merchant"?"داواکارییەکانی دوکان":"داواکارییەکان"}</h2><p className="mt-1 text-sm text-text-secondary">دۆخی داواکاری و ناونیشانی گەیاندن.</p></div><span className="rounded-full bg-surface-muted px-3 py-1 text-xs font-bold">{filteredOrders.length} لە {orders.length}</span></div><div className="mt-4 grid gap-3 sm:grid-cols-[minmax(0,1fr)_190px]"><label className="relative"><span className="sr-only">گەڕان لە داواکارییەکان</span><Search size={17} className="absolute right-3 top-1/2 -translate-y-1/2 text-text-muted"/><input value={orderSearch} onChange={e=>setOrderSearch(e.target.value)} placeholder="گەڕان بە ژمارە، دوکان یان ناونیشان..." className="w-full rounded-xl border border-border bg-surface px-10 py-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/20"/></label><label className="text-sm font-bold"><span className="sr-only">فلتەری دۆخی داواکاری</span><select value={orderStatusFilter} onChange={e=>setOrderStatusFilter(e.target.value)} className="w-full rounded-xl border border-border bg-surface px-3 py-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/20"><option value="all">هەموو دۆخەکان</option>{Object.entries(statusLabel).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label></div><div className="mt-4 space-y-3">{orders.length===0?<div className="rounded-xl bg-surface-muted p-5 text-sm leading-7 text-text-secondary">هێشتا داواکارییەکی پەیوەندیدار تۆمار نەکراوە.</div>:filteredOrders.length===0?<div className="rounded-xl bg-surface-muted p-5 text-sm text-text-secondary">هیچ داواکارییەک لەگەڵ گەڕان و فلتەرەکە ناگونجێت.</div>:filteredOrders.map(o=><article key={o.id} className="rounded-xl border border-border p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><b>داواکاری #{o.id.slice(0,8)}</b><p className="mt-1 text-xs text-text-muted">{new Date(o.created_at).toLocaleString("ckb")}</p></div><span className="rounded-full bg-secondary px-3 py-1 text-xs font-bold text-primary">{statusLabel[o.status]||o.status}</span></div>{(Array.isArray(o.stores)?o.stores[0]?.name:o.stores?.name)&&<p className="mt-2 text-sm font-bold text-text-secondary">دوکان: {Array.isArray(o.stores)?o.stores[0]?.name:o.stores?.name}</p>}<p className="mt-3 text-sm text-text-secondary">کۆی بەرهەم: {money(o.subtotal_iqd)} · گەیاندن: {money(o.delivery_fee_iqd)}</p>{o.delivery_address&&<p className="mt-2 text-sm leading-7">ناونیشان: {o.delivery_address}</p>}{profile?.approved_role==="merchant"&&o.status==="accepted"&&<button disabled={!!busyId} onClick={()=>void advanceOrder(o.id,"preparing")} className="mt-3 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-white">دەستپێکردنی ئامادەکردن</button>}{profile?.approved_role==="captain"&&o.status==="preparing"&&<button disabled={!!busyId} onClick={()=>void advanceOrder(o.id,"picked_up")} className="mt-3 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-white">وەرگرتنی بەرهەم</button>}{profile?.approved_role==="captain"&&o.status==="picked_up"&&<button disabled={!!busyId} onClick={()=>void advanceOrder(o.id,"delivering")} className="mt-3 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-white">دەستپێکردنی گەیاندن</button>}{profile?.approved_role==="captain"&&o.status==="delivering"&&<button disabled={!!busyId} onClick={()=>void advanceOrder(o.id,"delivered")} className="mt-3 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-white">تەواوکردنی گەیاندن</button>}</article>)}</div></div>
     </div>}
     {tab==="admin"&&isAdmin&&<div className="space-y-5">
      <div className="grid gap-3 sm:grid-cols-3"><article className={panel}><p className="text-sm text-text-secondary">داواکاریی ڕۆڵ</p><h2 className="mt-2 text-2xl font-black">{pendingRoles.length}</h2></article><article className={panel}><p className="text-sm text-text-secondary">داواکاریی جزدان</p><h2 className="mt-2 text-2xl font-black">{pendingTopups.length}</h2></article><article className={panel}><p className="text-sm text-text-secondary">دوکانی چاوەڕوان</p><h2 className="mt-2 text-2xl font-black">{pendingStores.length}</h2></article></div>
      <div className={panel}><h2 className="text-lg font-black">پەسەندکردنی ڕۆڵ</h2><div className="mt-4 space-y-3">{pendingRoles.length===0?<p className="text-sm text-text-secondary">هیچ داواکارییەکی چاوەڕوان نییە.</p>:pendingRoles.map(p=><article key={p.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border p-4"><div><b>{p.display_name||"بەکارهێنەر"}</b><p className="mt-1 text-sm text-text-secondary">{roleLabel[p.requested_role]||p.requested_role} · {p.phone||"ژمارەی مۆبایل نییە"}</p></div><div className="flex gap-2"><button disabled={!!busyId} onClick={()=>void reviewRole(p.id,true)} className="rounded-lg bg-primary px-3 py-2 text-sm font-bold text-white disabled:opacity-50">پەسەندکردن</button><button disabled={!!busyId} onClick={()=>void reviewRole(p.id,false)} className="rounded-lg border border-danger/30 px-3 py-2 text-sm font-bold text-danger disabled:opacity-50">ڕەتکردنەوە</button></div></article>)}</div></div>
      <div className={panel}><h2 className="text-lg font-black">پەسەندکردنی دوکان</h2><div className="mt-4 space-y-3">{pendingStores.length===0?<p className="text-sm text-text-secondary">دوکانی چاوەڕوان نییە.</p>:pendingStores.map(s=><article key={s.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border p-4"><div><b>{s.name}</b><p className="mt-1 text-sm text-text-secondary">{categoryLabel[s.category]||s.category}</p></div><div className="flex gap-2"><button disabled={!!busyId} onClick={()=>void reviewStore(s.id,true)} className="rounded-lg bg-primary px-3 py-2 text-sm font-bold text-white">پەسەندکردن</button><button disabled={!!busyId} onClick={()=>void reviewStore(s.id,false)} className="rounded-lg border border-danger/30 px-3 py-2 text-sm font-bold text-danger">ڕەتکردنەوە</button></div></article>)}</div></div>
      <div className={panel}><h2 className="text-lg font-black">داواکاریی زیادکردنی باڵانس</h2><div className="mt-4 space-y-3">{pendingTopups.length===0?<p className="text-sm text-text-secondary">داواکاریی جزدان نییە.</p>:pendingTopups.map(t=><article key={t.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border p-4"><div><b>{money(t.amount_iqd)}</b><p className="mt-1 text-xs text-text-muted">جۆر: {roleLabel[t.wallets?.owner_type||""]||t.wallets?.owner_type||"جزدان"} · {new Date(t.created_at).toLocaleString("ckb")}</p></div><div className="flex gap-2"><button disabled={!!busyId} onClick={()=>void reviewTopup(t.id,true)} className="rounded-lg bg-primary px-3 py-2 text-sm font-bold text-white">پەسەندکردن</button><button disabled={!!busyId} onClick={()=>void reviewTopup(t.id,false)} className="rounded-lg border border-danger/30 px-3 py-2 text-sm font-bold text-danger">ڕەتکردنەوە</button></div></article>)}</div></div>
      <div className={panel}><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-black">هەموو داواکارییەکان</h2><p className="mt-1 text-sm text-text-secondary">پیشاندانی تەنها؛ گۆڕینی دۆخی داواکاری لەم لیستەوە ئەنجام نادرێت.</p></div><label className="relative min-w-[220px] flex-1 sm:max-w-sm"><span className="sr-only">گەڕان لە هەموو داواکارییەکان</span><Search size={17} className="absolute right-3 top-1/2 -translate-y-1/2 text-text-muted"/><input value={adminOrderSearch} onChange={e=>setAdminOrderSearch(e.target.value)} placeholder="گەڕان بە ژمارە، دۆخ یان ناونیشان..." className="w-full rounded-xl border border-border bg-surface px-10 py-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/20"/></label></div><div className="mt-4 space-y-2">{filteredAdminOrders.slice(0,50).map(o=><div key={o.id} className="flex flex-wrap justify-between gap-2 rounded-lg bg-surface-muted p-3 text-sm"><span>#{o.id.slice(0,8)} · {o.stores&&(Array.isArray(o.stores)?o.stores[0]?.name:o.stores.name)?((Array.isArray(o.stores)?o.stores[0]?.name:o.stores.name)+" · "):""}{statusLabel[o.status]||o.status}</span><b>{money(o.subtotal_iqd+o.delivery_fee_iqd)}</b></div>)}{filteredAdminOrders.length===0&&<p className="rounded-xl bg-surface-muted p-4 text-sm text-text-secondary">هیچ داواکارییەک نەدۆزرایەوە.</p>}</div></div>
     </div>}
    </section>
   </div>
   <footer className="mt-8 hidden border-t border-border py-5 text-center text-xs leading-6 text-text-muted md:block">شاخ دێلڤەری · بەڕێوەبردنی هەژمار و خزمەتگوزارییەکان</footer>
  </div>
  <nav aria-label="ناوبەری مۆبایل" className="fixed inset-x-0 bottom-0 z-40 border-t border-border bg-surface/95 px-2 pb-[max(0.4rem,env(safe-area-inset-bottom))] pt-2 shadow-popover backdrop-blur lg:hidden"><div className="mx-auto grid max-w-xl grid-cols-4 gap-1">{[{label:"سەرەتا",href:"/",icon:Activity},{label:"داشبۆرد",href:"/dashboard",icon:LayoutDashboard},{label:"هەژمار",href:"/dashboard",icon:UserRound},{label:"بازاڕ",href:"/#products",icon:Store}].map((n,i)=><Link key={n.label} href={n.href} onClick={()=>{if(i===2)setTab("profile");}} className={"flex flex-col items-center justify-center gap-1 rounded-xl py-2 text-[11px] font-bold "+(i===1?"bg-secondary text-primary":"text-text-secondary")}><n.icon size={19}/>{n.label}</Link>)}</div><p className="mt-1 text-center text-[9px] text-text-muted">شاخ · خزمەتگوزاریی مۆبایل</p></nav>
 </main>;
}
